-- QHEADERS: the outfiles' system column names, in order, for the csv headers.
CREATE TABLE QSTEST/FFDH AS (SELECT ORDINAL_POSITION AS POS, SYSTEM_COLUMN_NAME AS NAME FROM QSYS2/SYSCOLUMNS WHERE TABLE_SCHEMA = 'QSTEST' AND TABLE_NAME = 'FFD') WITH DATA;
CREATE TABLE QSTEST/LVLIDH AS (SELECT ORDINAL_POSITION AS POS, SYSTEM_COLUMN_NAME AS NAME FROM QSYS2/SYSCOLUMNS WHERE TABLE_SCHEMA = 'QSTEST' AND TABLE_NAME = 'LVLID') WITH DATA;
CREATE TABLE QSTEST/JRNH AS (SELECT ORDINAL_POSITION AS POS, SYSTEM_COLUMN_NAME AS NAME FROM QSYS2/SYSCOLUMNS WHERE TABLE_SCHEMA = 'QSTEST' AND TABLE_NAME = 'JRN') WITH DATA;
CREATE TABLE QSTEST/RLALOGH AS (SELECT ORDINAL_POSITION AS POS, SYSTEM_COLUMN_NAME AS NAME FROM QSYS2/SYSCOLUMNS WHERE TABLE_SCHEMA = 'QSTEST' AND TABLE_NAME = 'RLALOG') WITH DATA;
